/* 
Delete all duplicate rows, keeping only the EARLIEST signup (lowest `signup_timestamp`) for each email.
*/

DELETE FROM trial_signups
WHERE signup_id NOT IN (
        SELECT
            MIN(signup_id) OVER (PARTITION BY email ORDER BY signup_timestamp) AS signup_id
        FROM trial_signups
        );

SELECT * FROM trial_signups ORDER BY signup_id;
